b=Path("artifacts/node/115/hl-node").read_bytes()
assert hashlib.sha256(b).hexdigest()=="a6e2897cd051213d004802deca416e8eca62b7a8278fa39f249e98c3867b5301"
A={30042099: '498b004885c00f8490060000', 30043953: '488b8424f80100004c8b384d8b274d85e40f844a0400004d8b6f08bf90040000ff15298583044885c00f8449040000', 30044000: '4989c648c7000000000066c7802a04000000004c89a0300400004c89e848ffc04c8b8424500100000f842d0400004d8934246641c784242804000000004d893749894708', 30044079: '410fb7862a0400004883f80b0f831e0400008d48016641898e2a040000488d1440488bb424e0000000498974d6180f108424d0000000410f1144d608', 30044139: '488d14c0488bb424a00000004989b4d6500100000f284424600f284c24700f289424800000000f289c2490000000410f119cd640010000410f1194d630010000410f118cd620010000410f1184d61001000049899cc6380400004c893366898b28040000'}
def valid(d):
 return all(d[x-0x1000:x-0x1000+len(bytes.fromhex(v))]==bytes.fromhex(v) for x,v in A.items()) and 0x1ca67ff+struct.unpack_from("<i",d,0x1ca67fb-0x1000)[0]==0x1ca6e8f and 0x1ca6f60+struct.unpack_from("<i",d,0x1ca6f5c-0x1000)[0]==0x1ca73a9
